import { languageSelector } from "~/renderer/reducers/settings";

const LEDGER_DOMAIN = "www.ledger.com";
const SUPPORT_DOMAIN = "support.ledger.com";
const SHOP_DOMAIN = "shop.ledger.com";

type LocaleMap = Record<string, string>;

// Locale overrides for www.ledger.com. Locales not listed are inserted as-is.
const ledgerLocaleMap: LocaleMap = {
  pt: "pt-br",
  zh: "zh-hans",
};

// Locale overrides for support.ledger.com. Locales not listed are inserted as-is.
const supportLocaleMap: LocaleMap = {
  fr: "fr-fr",
  en: "en-us",
  zh: "zh-cn",
};

// Locale overrides for shop.ledger.com. Locales not listed are inserted as-is.
const shopLocaleMap: LocaleMap = {
  pt: "pt-br",
};

/**
 * Localizes URLs for Ledger's web properties based on the user's current
 * language setting in the app.
 *
 * The locale is read from the settings reducer and inserted into the URL
 * according to the conventions of each supported Ledger domain. URLs on any
 * other domain are returned unchanged.
 */
export function useLocalizedUrl(url: string): string {
  const locale = useSelector(languageSelector);

  let host: string;
  try {
    host = new URL(url).host;
  } catch {
    return url;
  }

  switch (host) {
    case LEDGER_DOMAIN: {
      const localizedSegment = ledgerLocaleMap[locale] ?? locale;
      return url.replace(`${LEDGER_DOMAIN}/`, `${LEDGER_DOMAIN}/${localizedSegment}/`);
    }
    case SUPPORT_DOMAIN: {
      const localizedSegment = supportLocaleMap[locale] ?? locale;
      return url.replace("/hc/", `/hc/${localizedSegment}/`);
    }
    case SHOP_DOMAIN: {
      const localizedSegment = shopLocaleMap[locale] ?? locale;
      return url.replace(`${SHOP_DOMAIN}/`, `${SHOP_DOMAIN}/${localizedSegment}/`);
    }
    default:
      return url;
  }
}

export default useLocalizedUrl;
